// Package: ModelContextProtocol
// Install: dotnet add package ModelContextProtocol --version 1.*

using ModelContextProtocol;
using ModelContextProtocol.Server;
using Microsoft.Extensions.AI;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport();

var app = builder.Build();
app.MapMcp();
app.Run();

// Tool implementation exposed via MCP
public class WeatherTools
{
    private readonly IWeatherRepository _repository;

    public WeatherTools(IWeatherRepository repository)
    {
        _repository = repository;
    }

    [McpServerTool(Name = "get_weather")]
    public Task<WeatherInfo> GetWeatherAsync(
        string city,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(city);

        try
        {
            WeatherInfo? info = _repository.FindByCity(city);
            if (info is null)
                throw new InvalidOperationException($"Weather data not found for '{city}'.");

            return Task.FromResult(info);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Weather lookup failed: {ex.Message}");
            throw;
        }
    }
}

// How an AI client sees this tool:
// Tool: get_weather
// Description: Get current weather information for a city.
// Parameters:
//   - city (string, required): The city name
